me:AddMsg("[NAME]向陈佳宁打了个招呼，只见陈佳宁对[NAME]面无表情的点了点头，很随意的向你丢了一些东西。");			
					me:AddMemery(sN);me:AddTreeExp(me:GetDaoHang()*1000);	
